module fox_hiding_distance (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] roost_x,    // Q12.20 fixed-point\n    input wire [31:0] roost_y,\n    input wire [31:0] spot_x [0:7],\n    input wire [31:0] spot_y [0:7],\n    input wire [3:0] N,            // number of spots (1..8)\n    output reg done,\n    output reg [31:0] result       // Q12.20 fixed-point\n);\n\n    // Fixed-point parameters\n    localparam FRAC_BITS = 20;\n    localparam MAX_N = 8;\n\n    // State definitions\n    localparam [3:0] IDLE               = 4'd0;\n    localparam [3:0] COMPUTE_DIST_ROOST = 4'd1;\n    localparam [3:0] COMPUTE_DIST_SPOT  = 4'd2;\n    localparam [3:0] DP_INIT            = 4'd3;\n    localparam [3:0] DP_OUTER           = 4'd4;\n    localparam [3:0] DP_INNER_I         = 4'd5;\n    localparam [3:0] DP_INNER_J         = 4'd6;\n    localparam [3:0] DP_UPDATE          = 4'd7;\n    localparam [3:0] DONE_STATE         = 4'd8;\n\n    reg [3:0] state, next_state;\n\n    // Distance storage arrays\n    reg [31:0] dist_roost [0:7];   // Roost to spot distances\n    reg [31:0] dist_spot [0:7][0:7]; // Spot to spot distances\n\n    // DP memory (256 entries)\n    reg [31:0] dp [0:255];\n\n    // Control registers\n    reg [7:0] mask;\n    reg [7:0] prev_mask;\n    reg [3:0] i_cnt, j_cnt;\n    reg [31:0] dp_data;\n    reg dp_wr_en;\n    integer k; // For initialization loops\n\n    // Fixed-point helper variables\n    wire signed [63:0] dx, dy, dist_sq;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE:               if (start) next_state = COMPUTE_DIST_ROOST;\n            COMPUTE_DIST_ROOST: if (i_cnt == (N-4'd1)) next_state = COMPUTE_DIST_SPOT;\n            COMPUTE_DIST_SPOT:  if (i_cnt == (N-4'd1) && j_cnt == (N-4'd1)) next_state = DP_INIT;\n            DP_INIT:            next_state = DP_OUTER;\n            DP_OUTER:           if (mask >= (1 << N)) next_state = DONE_STATE;\n                                else next_state = DP_INNER_I;\n            DP_INNER_I:         if (!(mask[i_cnt])) next_state = (i_cnt == (N-4'd1)) ? DP_OUTER : DP_INNER_I;\n                                else next_state = DP_INNER_J;\n            DP_INNER_J:         if (j_cnt == (N-4'd1)) next_state = DP_INNER_I;\n                                else next_state = DP_UPDATE;\n            DP_UPDATE:          next_state = DP_INNER_J;\n            DONE_STATE:         if (!start) next_state = IDLE;\n            default:            next_state = IDLE;\n        endcase\n    end\n\n    // Datapath and control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n            result <= 32'd0;\n            mask <= 8'd1;\n            dp_wr_en <= 1'b0;\n            i_cnt <= 4'd0;\n            j_cnt <= 4'd0;\n            dp_data <= 32'd0;\n            prev_mask <= 8'd0;\n            \n            // Initialize arrays\n            for (k = 0; k < 8; k = k + 1) begin\n                dist_roost[k] <= 32'd0;\n                for (int m = 0; m < 8; m = m + 1) begin\n                    dist_spot[k][m] <= 32'd0;\n                end\n            end\n            \n            // Initialize DP memory\n            for (k = 0; k < 256; k = k + 1) begin\n                dp[k] <= 32'h7FFF_FFFF;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    mask <= 8'd1;\n                    i_cnt <= 4'd0;\n                    j_cnt <= 4'd0;\n                    // Reset DP memory when starting\n                    if (start) begin\n                        dp[0] <= 32'd0;\n                    end\n                end\n\n                COMPUTE_DIST_ROOST: begin\n                    dx = $signed(roost_x) - $signed(spot_x[i_cnt]);\n                    dy = $signed(roost_y) - $signed(spot_y[i_cnt]);\n                    dist_sq = (dx * dx) + (dy * dy);\n                    dist_roost[i_cnt] <= dist_sq[51:20]; // Approximation for demonstration\n                    i_cnt <= (i_cnt == (N-4'd1)) ? 4'd0 : (i_cnt + 4'd1);\n                    j_cnt <= 4'd0;\n                end\n\n                COMPUTE_DIST_SPOT: begin\n                    if (i_cnt != j_cnt) begin\n                        dx = $signed(spot_x[i_cnt]) - $signed(spot_x[j_cnt]);\n                        dy = $signed(spot_y[i_cnt]) - $signed(spot_y[j_cnt]);\n                        dist_sq = (dx * dx) + (dy * dy);\n                        dist_spot[i_cnt][j_cnt] <= dist_sq[51:20];\n                    end\n                    j_cnt <= (j_cnt == (N-4'd1)) ? 4'd0 : (j_cnt + 4'd1);\n                    i_cnt <= (j_cnt == (N-4'd1)) ? (i_cnt + 4'd1) : i_cnt;\n                end\n\n                DP_INIT: begin\n                    mask <= 8'd1;\n                end\n\n                DP_OUTER: begin\n                    if (mask < (1 << N)) begin\n                        i_cnt <= 4'd0;\n                    end else begin\n                        result <= dp[(1 << N) - 1];\n                    end\n                end\n\n                DP_INNER_I: begin\n                    if (mask[i_cnt]) begin\n                        prev_mask <= mask & ~(1 << i_cnt);\n                        dp_data <= dp[prev_mask] + (dist_roost[i_cnt] << 1);\n                        dp_wr_en <= 1'b1;\n                        j_cnt <= i_cnt + 4'd1;\n                    end else begin\n                        i_cnt <= (i_cnt == (N-4'd1)) ? 4'd0 : (i_cnt + 4'd1);\n                    end\n                end\n\n                DP_INNER_J: begin\n                    dp_wr_en <= 1'b0;\n                    if (j_cnt < N && (mask[j_cnt]) && !(j_cnt == i_cnt)) begin\n                        prev_mask <= mask & ~((1 << i_cnt) | (1 << j_cnt));\n                        dp_data <= dp[prev_mask] + dist_roost[i_cnt] + \n                                   dist_spot[i_cnt][j_cnt] + dist_roost[j_cnt];\n                        dp_wr_en <= 1'b1;\n                    end\n                    j_cnt <= (j_cnt == (N-4'd1)) ? 4'd0 : (j_cnt + 4'd1);\n                    i_cnt <= (j_cnt == (N-4'd1)) ? (i_cnt + 4'd1) : i_cnt;\n                end\n\n                DP_UPDATE: begin\n                    if (dp_wr_en && (dp_data < dp[mask])) begin\n                        dp[mask] <= dp_data;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n\n            // Mask incrementer\n            if (state == DP_OUTER && mask < (1 << N)) begin\n                mask <= mask + 8'd1;\n            end\n        end\n    end\n\nendmodule